// Validate index range from UF's internal storage
size_t n = uf->e.size();
if (n == 0) { FUZZ_BAIL(); }
int x = (int)((unsigned)(*FUZZ_PARAM(unsigned int)) % (unsigned)n);
int sz = uf->size(x);
FUZZ_ASSERT(sz > 0, "Component size must be positive");
(void)sz;
// Return uf as output to keep it in the pool

// Ensure UF has a valid, non-empty domain for indices
size_t n = uf->e.size();
if (n == 0) { FUZZ_BAIL(); }
// Choose a valid index within [0, n)
int x = (int)((unsigned)(*FUZZ_PARAM(unsigned int)) % (unsigned)n);
// Call target: UF::find, which may perform path compression
int r1 = uf->find(x);
// Basic correctness: representative index must be within range and denote a root entry (negative size)
FUZZ_ASSERT(r1 >= 0 && (size_t)r1 < n, "UF::find must return in-range representative");
FUZZ_ASSERT(uf->e[r1] < 0, "Representative must have negative size entry");
// Idempotence: find(x) should be stable after path compression
int r2 = uf->find(x);
FUZZ_ASSERT(r1 == r2, "UF::find should be idempotent for same element");
// Return uf to keep it in the pool
// Validation: indices are bounded; root invariant and idempotence are asserted; uf retained as output.

// Validate UF has at least one element to operate on
size_t n = uf->e.size();
if (n == 0) { FUZZ_BAIL(); }
// Choose two valid indices
int a = (int)((unsigned)(*FUZZ_PARAM(unsigned int)) % (unsigned)n);
int b = (int)((unsigned)(*FUZZ_PARAM(unsigned int)) % (unsigned)n);
// Capture pre-state: roots and component sizes
int ra = uf->find(a);
int rb = uf->find(b);
FUZZ_ASSERT(ra >= 0 && (size_t)ra < n, "Pre root a in range");
FUZZ_ASSERT(rb >= 0 && (size_t)rb < n, "Pre root b in range");
int sa = -uf->e[ra];
int sb = -uf->e[rb];
FUZZ_ASSERT(sa > 0 && sb > 0, "Pre component sizes must be positive");
// Invoke target: union by size; may or may not merge
bool merged = uf->join(a, b);
if (ra == rb) {
    // Already same set: join must return false and sizes remain unchanged
    FUZZ_ASSERT(!merged, "UF::join must return false when joining within same set");
    int r = uf->find(a);
    FUZZ_ASSERT(r == ra, "Root should be unchanged when no merge occurs");
    FUZZ_ASSERT(-uf->e[r] == sa, "Component size must remain unchanged when no merge occurs");
} else {
    // Different sets: join must return true and sizes must add up
    FUZZ_ASSERT(merged, "UF::join must return true when merging distinct sets");
    int r_after_a = uf->find(a);
    int r_after_b = uf->find(b);
    FUZZ_ASSERT(r_after_a == r_after_b, "After merge, both elements must share the same root");
    int r = r_after_a;
    FUZZ_ASSERT(r >= 0 && (size_t)r < n, "Post root in range");
    int s_new = -uf->e[r];
    FUZZ_ASSERT(s_new == sa + sb, "Merged component size must equal sum of sizes");
}
// Return uf to keep it in the pool
// Validation: indices constrained; pre/post invariants checked; both merge and no-merge paths covered; uf retained as output.

// Construct a non-empty UF instance with bounded size and optional random unions to diversify state
// Choose size n in [1, 512] to satisfy downstream stubs (they require n > 0) and keep allocations small
unsigned int raw_n = (unsigned int)*FUZZ_PARAM(unsigned int);
int n = (int)(raw_n % 512u) + 1; // ensure n >= 1
// Allocate UF on the heap (API is user-managed); output must not be null
struct UF *uf = new UF(n);
// Record size as metadata for potential downstream consumers
FUZZ_SET_ATTR_INT(uf, "n", n);

// Diversify internal forest: perform up to ~3n union operations using deterministic indices
// Note: FUZZ_PARAM invoked in loops returns the same value; derive a simple LCG per-iteration from seeds
unsigned int seedA = (unsigned int)*FUZZ_PARAM(unsigned int);
unsigned int seedB = (unsigned int)*FUZZ_PARAM(unsigned int);
unsigned int raw_m = (unsigned int)*FUZZ_PARAM(unsigned int);
int m = (int)(raw_m % (3u * (unsigned int)n + 1u)); // m in [0, 3n]
for (int i = 0; i < m; ++i) {
    // LCG step: new = 1664525*x + 1013904223
    unsigned int ai = seedA + (unsigned int)(1664525u * (unsigned int)i + 1013904223u);
    unsigned int bi = seedB + (unsigned int)(22695477u * (unsigned int)i + 1u);
    int a = (int)(ai % (unsigned int)n);
    int b = (int)(bi % (unsigned int)n);
    // Indices are guaranteed to be within [0, n)
    (void)uf->join(a, b);
}
FUZZ_SET_ATTR_INT(uf, "unions", m);

// Basic invariant checks to ensure a valid UF state after construction
// All entries must either be negative (root with size) or a parent index within range
for (int i = 0; i < n; ++i) {
    int v = uf->e[i];
    if (v >= 0) {
        // parent pointer must be in range
        if (!(v >= 0 && v < n)) { FUZZ_BAIL(); }
    }
}

// Output: uf (kept alive by the fuzzer runtime pool)
// Validation: Ensures n >= 1, bounds-safe unions, and parent/index invariants; returns a non-null UF instance.
